  </head>
  <body>
    <main>
      <section class="card" aria-labelledby="form-title">
        <h1 id="form-title">Terms of use</h1>
        <p class="intro">Review and confirm your consent to continue.</p>

        <form id="consent-form" novalidate>
          <div class="form-field">
            <input
              type="checkbox"
              id="terms"
              name="terms"
              required
              aria-describedby="terms-helper terms-error"
            >
            <label for="terms">I agree to the terms of use</label>
            <p class="helper-text" id="terms-helper">Required to submit this form.</p>
          </div>

          <p class="error-message" id="terms-error"></p>
          <button type="submit">Submit consent</button>
