 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Terms Consent Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0f172a;
         --panel: #172033;
         --panel-border: #334155;
         --text: #f8fafc;
         --muted: #cbd5e1;
         --accent: #60a5fa;
         --accent-strong: #93c5fd;
         --button: #2563eb;
         --button-hover: #1d4ed8;
         --error: #fca5a5;
         --shadow: #020617;
       }

       * {
         box-sizing: border-box;
       }

       body {
         min-height: 100vh;
         margin: 0;
         display: grid;
         place-items: center;
         padding: 1rem;
         background:
           radial-gradient(circle at top left, #1e3a8a 0, transparent 32rem),
           linear-gradient(135deg, var(--bg), #020617);
         color: var(--text);
         font-family: Arial, Helvetica, sans-serif;
         line-height: 1.5;
       }

       main {
         width: min(100%, 30rem);
       }

       .card {
         padding: clamp(1.5rem, 5vw, 2.5rem);
