         background: var(--panel);
         box-shadow: 0 1.5rem 4rem var(--shadow);
       }

       h1 {
         margin: 0 0 0.5rem;
         font-size: clamp(1.75rem, 8vw, 2.5rem);
         line-height: 1.1;
       }

       .intro {
         margin: 0 0 1.5rem;
         color: var(--muted);
       }

