         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.75rem;
         padding: 1rem;
         border: 1px solid var(--panel-border);
         border-radius: 0.875rem;
         background: #0f172a;
       }

       input[type="checkbox"] {
         width: 1.25rem;
         height: 1.25rem;
         margin: 0.2rem 0 0;
         accent-color: var(--accent);
       }

       label {
         font-weight: 700;
       }

       .helper-text {
         grid-column: 2;
         margin: -0.25rem 0 0;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .error-message {
         min-height: 1.5rem;
         margin: 0.75rem 0 1rem;
         color: var(--error);
         font-weight: 700;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 999px;
         padding: 0.875rem 1.25rem;
         background: var(--button);
         color: #ffffff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
