   <body>
     <main>
       <section class="card" aria-labelledby="form-title">
         <h1 id="form-title">Terms of use</h1>
         <p class="intro">Review and confirm your consent to continue.</p>

         <form id="consent-form" novalidate>
           <div class="form-field">
             <input
               type="checkbox"
               id="terms"
               name="terms"
               required
               aria-describedby="terms-helper terms-error"
             >
             <label for="terms">I agree to the terms of use</label>
             <p class="helper-text" id="terms-helper">Required to submit this form.</p>
           </div>

           <p class="error-message" id="terms-error"></p>
           <button type="submit">Submit consent</button>
           <p class="status" id="form-status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#consent-form");
       const checkbox = document.querySelector("#terms");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       function updateValidationMessage() {
         if (checkbox.checked) {
           checkbox.removeAttribute("aria-invalid");
           error.textContent = "";
           return true;
         }

         checkbox.setAttribute("aria-invalid", "true");
         error.textContent = "Please agree to the terms of use before submitting.";
         return false;
       }

       checkbox.addEventListener("change", () => {
         status.textContent = "";
         updateValidationMessage();
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         status.textContent = "";

         if (!updateValidationMessage()) {
           checkbox.focus();
           return;
         }

         status.textContent = "Consent submitted. Thank you.";
         form.reset();
       });
     </script>
